async function main(adminRoleName,prefix,YTKEY,passes,helpshow,token){
const { Client } = require('discord.js');
const yt = require('ytdl-core');
const client = new Client();
const YouTube = require('youtube-node');
const youTube = new YouTube();
youTube.setKey(YTKEY);

let queue = {};

const commands = {
	'play': (msg) => {
		if (queue[msg.guild.id] === undefined) return msg.channel.send(`Add some songs to the queue first with ${prefix}add`);
		if (!msg.guild.voiceConnection) return commands.join(msg).then(() => commands.play(msg));
		if (queue[msg.guild.id].playing) return msg.channel.send('Already Playing');
		let dispatcher;
		queue[msg.guild.id].playing = true;

		console.log(queue);
		(function play(song) {
			console.log(song);
			if (song === undefined) return msg.channel.send('Queue is empty').then(() => {
				queue[msg.guild.id].playing = false;
				msg.member.voiceChannel.leave();
			});
			msg.channel.send(`Playing: **${song.title}** as requested by: **${song.requester}**`);
			dispatcher = msg.guild.voiceConnection.playStream(yt(song.url, { audioonly: true }), { passes : passes });
			let collector = msg.channel.createMessageCollector(m => m);
			collector.on('collect', m => {
				if (m.author.bot) return
				if (m.content.startsWith(prefix + 'pause')) {
					const voiceChannel = msg.member.voiceChannel;
				if (!voiceChannel || voiceChannel.type !== 'voice') return msg.reply('I couldn\'t connect to your voice channel...');
					msg.channel.send('Paused.').then(() => {dispatcher.pause();});
				} else if (m.content.startsWith(prefix + 'resume')){
					const voiceChannel = msg.member.voiceChannel;
					if (!voiceChannel || voiceChannel.type !== 'voice') return msg.reply('I couldn\'t connect to your voice channel...');
					msg.channel.send('Resumed.').then(() => {dispatcher.resume();});
				} else if (m.content.startsWith(prefix + 'skip')){
					const voiceChannel = msg.member.voiceChannel;
					if (!voiceChannel || voiceChannel.type !== 'voice') return msg.reply('I couldn\'t connect to your voice channel...');
					msg.channel.send('Skipped.').then(() => {dispatcher.end();});
      	} else if (m.content.startsWith(prefix + 'disconnect')){
			const voiceChannel = msg.member.voiceChannel;
			if (!voiceChannel || voiceChannel.type !== 'voice') return msg.reply('I couldn\'t connect to your voice channel...');
        dispatcher.end();
          var song =  queue[msg.guild.id].songs.shift()
           if (song != undefined) {
             var songnum = queue[msg.guild.id].songs
             var i
           for (i; i < songnum.length; i++) {
            dispatcher.end();   
           }
				queue[msg.guild.id].playing = false; 
				msg.member.voiceChannel.leave();
              } else {
             msg.channel.send("Disconnected.").then(() => {
				queue[msg.guild.id].playing = false; 
				msg.member.voiceChannel.leave();
			});
          }
				} else if (m.content.startsWith(prefix + 'volume add')){
					const voiceChannel = msg.member.voiceChannel;
			if (!voiceChannel || voiceChannel.type !== 'voice') return msg.reply('I couldn\'t connect to your voice channel...');
					if (Math.round(dispatcher.volume*50) >= 100) return msg.channel.send(`Volume: ${Math.round(dispatcher.volume*50)}%`);
					dispatcher.setVolume(Math.min((dispatcher.volume*50 + (2*(m.content.split('+').length-1)))/50,2));
					msg.channel.send(`Volume: ${Math.round(dispatcher.volume*50)}%`);
				} else if (m.content.startsWith(prefix + 'volume remove')){
					const voiceChannel = msg.member.voiceChannel;
			if (!voiceChannel || voiceChannel.type !== 'voice') return msg.reply('I couldn\'t connect to your voice channel...');
					if (Math.round(dispatcher.volume*50) <= 0) return msg.channel.send(`Volume: ${Math.round(dispatcher.volume*50)}%`);
					dispatcher.setVolume(Math.max((dispatcher.volume*50 - (2*(m.content.split('-').length-1)))/50,0));
					msg.channel.send(`Volume: ${Math.round(dispatcher.volume*50)}%`);
				} else if (m.content.startsWith(prefix + 'time')){
					const voiceChannel = msg.member.voiceChannel;
			if (!voiceChannel || voiceChannel.type !== 'voice') return msg.reply('I couldn\'t connect to your voice channel...');
					msg.channel.send(`time: ${Math.floor(dispatcher.time / 60000)}:${Math.floor((dispatcher.time % 60000)/1000) <10 ? '0'+Math.floor((dispatcher.time % 60000)/1000) : Math.floor((dispatcher.time % 60000)/1000)}`);
				}
			});
			dispatcher.on('end', () => {
				collector.stop();
				play(queue[msg.guild.id].songs.shift());
			});
			dispatcher.on('error', (err) => {
				return msg.channel.send('error: ' + err).then(() => {
					collector.stop();
					play(queue[msg.guild.id].songs.shift());
				});
			});
		})(queue[msg.guild.id].songs.shift());
	},
	'join': (msg) => {
		return new Promise((resolve, reject) => {
			const voiceChannel = msg.member.voiceChannel;
			if (!voiceChannel || voiceChannel.type !== 'voice') return msg.reply('I couldn\'t connect to your voice channel...');
			voiceChannel.join().then(connection => resolve(connection)).catch(err => reject(err));
		});
	},
	'add': (msg) => {
		function addFromUrl(url) {
			msg.channel.send("*Adding...*");
			if (url == '' || url === undefined) return msg.channel.send(`You must add a YouTube video url after ${prefix}add`);
			yt.getInfo(url, (err, info) => {
				if (err) return msg.channel.send('Invalid YouTube Link: ' + err + '\n This may be caused by this selection being a channel.');
				if (!queue.hasOwnProperty(msg.guild.id)) queue[msg.guild.id] = {}, queue[msg.guild.id].playing = false, queue[msg.guild.id].songs = [];
				queue[msg.guild.id].songs.push({
					url: url,
					title: info.title,
					requester: msg.author.username
				});
				msg.channel.send(`Added **${info.title}** to the queue`);
			});
		}
		function addFromQuery(query) {
			youTube.search(query, 6, { type: 'video' }, function(error, result) {
				if (error) {
					msg.channel.send('Error:\n' + error);
				} else {
				  msg.channel.send(`Please select a choice: \n1. ${result.items[0]["snippet"].title} \n2. ${result.items[1]["snippet"].title} \n3. ${result.items[2]["snippet"].title} \n4. ${result.items[3]["snippet"].title} \n5. ${result.items[4]["snippet"].title} `)
				  let collector = msg.channel.createMessageCollector(m => m);
						collector.on('collect', m => {
					if (m.author.bot) return;
					collector.stop()
					if (m.content == "cancel" || isNaN(m.content) == true) {
					  m.channel.send("Canceled Prompt")
					} else {
					  console.log(m.content)
					  let url = `https://www.youtube.com/watch?v=` + result.items[Number(m.content) - 1]["id"].videoId ;
					addFromUrl(url);
					}
				});
				}
			});
		}
		if (msg.content === `${prefix}add`) return msg.reply(`You must add a YouTube video url after ${prefix}add`);
		let url = msg.content.split(' ')[1];
		if (url.includes("https://youtube.com/") || url.includes("https://www.youtube.com/") || url.includes("http://youtube.com/") || url.includes("http://www.youtube.com/") || url.includes("https://youtu.be/") || url.includes("https://www.youtu.be/") || url.includes("http://youtu.be/") || url.includes("http://www.youtu.be/")) {
			addFromUrl(url);
		} else {
			let query = msg.content.replace(`${prefix}add`, '');
			addFromQuery(query);
		}
	},
	'queue': (msg) => {
		if (queue[msg.guild.id] === undefined) return msg.channel.send(`Add some songs to the queue first with ${prefix}add`);
		let tosend = [];
		queue[msg.guild.id].songs.forEach((song, i) => { tosend.push(`${i+1}. ${song.title} - Requested by: ${song.requester}`);});
		msg.channel.send(`__**${msg.guild.name}'s Music Queue:**__ Currently **${tosend.length}** songs queued ${(tosend.length > 15 ? '*[Only next 15 shown]*' : '')}\n\`\`\`${tosend.slice(0,15).join('\n')}\`\`\``);
	},
	'help': (msg) => {
		if (helpshow != false) {
		let tosend = ['```js', prefix + 'join : "Join Voice channel of msg sender"',	prefix + 'add : "Add a valid youtube link to the queue"', prefix + 'queue : "Shows the current queue, up to 15 songs shown."', prefix + 'play : "Play the music queue if already joined to a voice channel"', '', 'the following commands only function while the play command is running:'.toUpperCase(), prefix + 'pause : "pauses the music"',	prefix + 'resume : "resumes the music"', prefix + 'skip : "skips the playing song"', prefix + 'time : "Shows the playtime of the song."',	'volume+(+++) : "increases volume by 2%/+"',	'volume-(---) : "decreases volume by 2%/-"',	'```'];
		msg.channel.send(tosend.join('\n'));
	}
	},
	'reboot': (msg) => {
		if (adminRoleName == false) return
		if(!message.member.roles.some(r=>[adminRoleName].includes(r.name)) ) // OPTIONAL - Checks if the sender has the specified roles to carry on further
		return message.reply("You can't use this command.");
		 process.exit(); //Requires a node module like Forever to work.
	}
};

client.on('ready', () => {
	console.log('ready!');
});

client.on('message', msg => {
	if (!msg.content.startsWith(prefix)) return;
	if (msg.author.bot) return
	if (!msg.guild) return
	if (commands.hasOwnProperty(msg.content.toLowerCase().slice(prefix.length).split(' ')[0])) commands[msg.content.toLowerCase().slice(prefix.length).split(' ')[0]](msg);
});
if (token != false) {
client.login(token);
}
}
module.exports.init = main;